import Foundation

/// Decides whether a chapter-list download request is large enough to ask before queueing.
enum LargeDownloadConfirmation {
    /// Requests of more chapters than this need confirmation when the setting is on.
    static let threshold = 50

    static let toggleAccessibilityIdentifier = "settings.downloads.confirmLargeDownloads"

    static func isRequired(chapterCount: Int, defaults: UserDefaults) -> Bool {
        false
    }
}

